PRAGMA foreign_keys = ON;
CREATE TABLE schema_migrations (version INTEGER PRIMARY KEY);
INSERT INTO schema_migrations VALUES (1);
CREATE TABLE tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, parent_id TEXT REFERENCES tenants(id), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','closed')), region TEXT NOT NULL, settings TEXT NOT NULL DEFAULT '{}', quota_bytes INTEGER NOT NULL DEFAULT 104857600, created_at INTEGER NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', locale TEXT NOT NULL DEFAULT 'en');
CREATE TABLE roles (tenant_id TEXT NOT NULL REFERENCES tenants(id), id TEXT NOT NULL, name TEXT NOT NULL, capabilities TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id));
CREATE TABLE memberships (tenant_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), role_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', clearance INTEGER NOT NULL DEFAULT 0, expires_at INTEGER, PRIMARY KEY(tenant_id,user_id), FOREIGN KEY(tenant_id,role_id) REFERENCES roles(tenant_id,id));
CREATE TABLE credentials (hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, mfa INTEGER NOT NULL DEFAULT 0);
CREATE TABLE groups (tenant_id TEXT NOT NULL REFERENCES tenants(id), id TEXT NOT NULL, name TEXT NOT NULL, PRIMARY KEY(tenant_id,id));
CREATE TABLE group_members (tenant_id TEXT NOT NULL, group_id TEXT NOT NULL, user_id TEXT NOT NULL, PRIMARY KEY(tenant_id,group_id,user_id), FOREIGN KEY(tenant_id,group_id) REFERENCES groups(tenant_id,id), FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id));
CREATE TABLE departments (tenant_id TEXT NOT NULL REFERENCES tenants(id), id TEXT NOT NULL, name TEXT NOT NULL, parent_id TEXT, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,parent_id) REFERENCES departments(tenant_id,id));
CREATE TABLE documents (tenant_id TEXT NOT NULL REFERENCES tenants(id), id TEXT NOT NULL, title TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'document', owner_id TEXT NOT NULL REFERENCES users(id), classification INTEGER NOT NULL DEFAULT 0, metadata TEXT NOT NULL DEFAULT '{}', state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','in_review','approved','rejected','deleted')), current_version INTEGER NOT NULL DEFAULT 0, is_record INTEGER NOT NULL DEFAULT 0, retain_until INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(tenant_id,id));
CREATE TABLE versions (tenant_id TEXT NOT NULL, document_id TEXT NOT NULL, number INTEGER NOT NULL, object_id TEXT NOT NULL UNIQUE, envelope TEXT NOT NULL, bytes INTEGER NOT NULL, digest TEXT NOT NULL, mime TEXT NOT NULL, author_id TEXT NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL, PRIMARY KEY(tenant_id,document_id,number), FOREIGN KEY(tenant_id,document_id) REFERENCES documents(tenant_id,id));
CREATE TABLE acl (tenant_id TEXT NOT NULL, document_id TEXT NOT NULL, subject_type TEXT NOT NULL CHECK(subject_type IN ('user','group','role')), subject_id TEXT NOT NULL, action TEXT NOT NULL, effect TEXT NOT NULL CHECK(effect IN ('allow','deny')), expires_at INTEGER, PRIMARY KEY(tenant_id,document_id,subject_type,subject_id,action), FOREIGN KEY(tenant_id,document_id) REFERENCES documents(tenant_id,id));
CREATE TABLE holds (tenant_id TEXT NOT NULL, document_id TEXT NOT NULL, id TEXT NOT NULL, reason TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), released_by TEXT REFERENCES users(id), created_at INTEGER NOT NULL, released_at INTEGER, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,document_id) REFERENCES documents(tenant_id,id));
CREATE TABLE workflows (tenant_id TEXT NOT NULL, document_id TEXT NOT NULL, id TEXT NOT NULL, version INTEGER NOT NULL, requested_by TEXT NOT NULL REFERENCES users(id), state TEXT NOT NULL DEFAULT 'pending', decided_by TEXT REFERENCES users(id), decided_at INTEGER, created_at INTEGER NOT NULL, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,document_id,version) REFERENCES versions(tenant_id,document_id,number));
CREATE UNIQUE INDEX one_pending_workflow ON workflows(tenant_id,document_id) WHERE state='pending';
CREATE TABLE comments (tenant_id TEXT NOT NULL, document_id TEXT NOT NULL, id TEXT NOT NULL, version INTEGER NOT NULL, author_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,document_id,version) REFERENCES versions(tenant_id,document_id,number));
CREATE TABLE dispositions (tenant_id TEXT NOT NULL, document_id TEXT NOT NULL, id TEXT NOT NULL, version INTEGER NOT NULL, requested_by TEXT NOT NULL REFERENCES users(id), approved_by TEXT REFERENCES users(id), approved_at INTEGER, created_at INTEGER NOT NULL, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,document_id,version) REFERENCES versions(tenant_id,document_id,number));
CREATE TABLE audit (sequence INTEGER PRIMARY KEY AUTOINCREMENT, tenant_id TEXT NOT NULL REFERENCES tenants(id), actor_id TEXT NOT NULL, action TEXT NOT NULL, resource_id TEXT NOT NULL, outcome TEXT NOT NULL, reason TEXT NOT NULL, at INTEGER NOT NULL, request_id TEXT NOT NULL, previous_hash TEXT NOT NULL, hash TEXT NOT NULL);
CREATE INDEX audit_tenant ON audit(tenant_id,sequence);
CREATE INDEX documents_tenant ON documents(tenant_id,state,updated_at);
CREATE TABLE outbox (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), event TEXT NOT NULL, resource_id TEXT NOT NULL, created_at INTEGER NOT NULL, delivered_at INTEGER);
CREATE TABLE notifications (tenant_id TEXT NOT NULL, user_id TEXT NOT NULL, id TEXT NOT NULL, event TEXT NOT NULL, resource_id TEXT NOT NULL, read_at INTEGER, created_at INTEGER NOT NULL, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id));
CREATE TABLE rate_limits (tenant_id TEXT NOT NULL REFERENCES tenants(id), user_id TEXT NOT NULL, window INTEGER NOT NULL, requests INTEGER NOT NULL, PRIMARY KEY(tenant_id,user_id,window));
CREATE TABLE bookmarks (tenant_id TEXT NOT NULL, document_id TEXT NOT NULL, user_id TEXT NOT NULL, PRIMARY KEY(tenant_id,document_id,user_id), FOREIGN KEY(tenant_id,document_id) REFERENCES documents(tenant_id,id), FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id));
CREATE TRIGGER versions_immutable_update BEFORE UPDATE ON versions BEGIN SELECT RAISE(ABORT,'immutable_version'); END;
CREATE TRIGGER versions_immutable_delete BEFORE DELETE ON versions BEGIN SELECT RAISE(ABORT,'immutable_version'); END;
CREATE TRIGGER audit_immutable_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'immutable_audit'); END;
CREATE TRIGGER audit_immutable_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'immutable_audit'); END;
